def merge_and_clean_data(customers, orders):
    # customers: dict of id -> name
    # orders: list of dicts with 'id', 'customer_id', 'amount'
    seen_order_ids = set()
    cleaned_orders = []
    for o in orders:
        order_id = o.get("id")
        if not order_id or order_id in seen_order_ids:
            continue
        seen_order_ids.add(order_id)

        try:
            amt = float(str(o.get("amount", 0)).strip())
        except (ValueError, TypeError):
            continue

        cust_id = o.get("customer_id")
        cust_name = customers.get(cust_id, "Unknown")

        cleaned_orders.append({
            "order_id": order_id,
            "customer_name": cust_name,
            "amount": amt
        })
    return sorted(cleaned_orders, key=lambda x: x["order_id"])
